import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[] array, char separator, int startIndex, int endIndex)
 * 
 * Note: The provided implementation contains a 'if (false)' block which prevents 
 * the separator from ever being appended. The tests reflect the actual logic 
 * provided in the snippet.
 */
public class StringUtils_join_TriageGen1Test {

    @Test
    public void testJoin_NullArray() {
        assertNull("Should return null if array is null", StringUtils.join(null, ',', 0, 0));
    }

    @Test
    public void testJoin_NoOfItemsZero() {
        Object[] array = {"a", "b", "c"};
        assertEquals("Should return empty string if endIndex equals startIndex", "", StringUtils.join(array, ',', 1, 1));
    }

    @Test
    public void testJoin_NoOfItemsNegative() {
        Object[] array = {"a", "b", "c"};
        assertEquals("Should return empty string if endIndex is less than startIndex", "", StringUtils.join(array, ',', 2, 1));
    }

    @Test
    public void testJoin_SingleElement() {
        Object[] array = {"a"};
        // noOfItems = 1 - 0 = 1. Loop runs once. 
        // Note: separator is skipped due to 'if (false)' in source.
        assertEquals("Should return the element itself", "a", StringUtils.join(array, ',', 0, 1));
    }

    @Test
    public void testJoin_MultipleElements() {
        Object[] array = {"a", "b", "c"};
        // noOfItems = 3 - 0 = 3. Loop runs for i=0, 1, 2.
        // Note: separator is skipped due to 'if (false)' in source.
        assertEquals("Should return concatenated elements without separator due to 'if (false)'", "abc", StringUtils.join(array, ',', 0, 3));
    }

    @Test
    public void testJoin_WithStartIndexAndEndIndex() {
        Object[] array = {"a", "b", "c", "d"};
        // startIndex = 1, endIndex = 3. Elements: array[1]="b", array[2]="c"
        assertEquals("Should only join elements within the specified range", "bc", StringUtils.join(array, ',', 1, 3));
    }

    @Test
    public void testJoin_WithNullElementsInArray() {
        Object[] array = {"a", null, "c"};
        // noOfItems = 3. Loop i=0 (a), i=1 (null - skip), i=2 (c)
        // Note: separator is skipped due to 'if (false)' in source.
        assertEquals("Should skip null elements in the array", "ac", StringUtils.join(array, ',', 0, 3));
    }

    @Test
    public void testJoin_MixedTypes() {
        Object[] array = {"a", 1, true};
        // noOfItems = 3.
        assertEquals("Should handle different object types via toString()", "a1true", StringUtils.join(array, ',', 0, 3));
    }
}
